const useAccessCode = `-- name: UseAccessCode :one
UPDATE access_codes SET uses = uses + 1
WHERE code = $1::text
  AND revoked_at IS NULL
  AND (expires_at IS NULL OR expires_at > now())
  AND uses < max_uses
RETURNING code
`

// Admits one more account on a beta code that is live: not revoked, not
// expired and not used up. No row when it cannot.
func (q *Queries) UseAccessCode(ctx context.Context, code string) (string, error) {
	row := q.db.QueryRow(ctx, useAccessCode, code)
	var code_2 string
	err := row.Scan(&code_2)
	return code_2, err
}

const useMemberInvite = `-- name: UseMemberInvite :one
UPDATE invites i SET signups = i.signups + 1
FROM users u, perspectives p
WHERE i.code = $1::text
  AND u.id = i.inviter_id AND u.deleted_at IS NULL AND u.suspended_at IS NULL
  AND p.id = i.perspective_id AND p.status = 'PERSPECTIVE_STATUS_PUBLISHED'
  AND p.deleted_at IS NULL AND p.hidden_at IS NULL
  AND i.signups < $2::integer
RETURNING i.code
`

type UseMemberInviteParams struct {
	Code       string
	MaxSignups int32
}

// Admits one more sign-up on a member's invite link while it is live: the
// inviter is in good standing, the shared story is still readable, and the
// link has admitted fewer than max_signups. No row when it cannot.
func (q *Queries) UseMemberInvite(ctx context.Context, arg UseMemberInviteParams) (string, error) {
	row := q.db.QueryRow(ctx, useMemberInvite, arg.Code, arg.MaxSignups)
	var code string
	err := row.Scan(&code)
	return code, err
}

const writeStanding = `-- name: WriteStanding :one
SELECT (email_verified_at IS NOT NULL)::boolean AS verified, (suspended_at IS NOT NULL)::boolean AS suspended
FROM users
WHERE id = $1 AND deleted_at IS NULL
`

type WriteStandingRow struct {
	Verified  bool
	Suspended bool
}

// The shared write gate's inputs for a live account: whether its email is
// verified and whether moderation suspended it.
func (q *Queries) WriteStanding(ctx context.Context, id uuid.UUID) (WriteStandingRow, error) {
	row := q.db.QueryRow(ctx, writeStanding, id)
	var i WriteStandingRow
	err := row.Scan(&i.Verified, &i.Suspended)
	return i, err
}
